cd /tmp/<path>; cat > /tmp/sim.py <<'E'
import sys
L=[l.split(';')[0].split() for l in open('prog.pw9')]
P=[l for l in L if l]
R=dict(a=0,b=0,c=0,d=0)
v=lambda x:R[x] if x in R else int(x)
pc=0;n=0;s=0
while 0<=pc<len(P):
    i=P[pc];o=i[0];n+=1;pc+=1
    if o=='set':R[i[1]]=v(i[2])%65536
    elif o=='add':R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif o=='mul':R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif o=='mod':
        if v(i[2])>0:R[i[1]]%=v(i[2])
    elif o=='dec':R[i[1]]=max(0,R[i[1]]-1)
    elif o=='jnz':
        if v(i[1])!=0:pc+=v(i[2])-1
    elif o=='skp':
        if v(i[1])<v(i[2]):pc+=1
    elif o=='out':s+=v(i[1])
    else:raise Exception(i)
print(s,n)
E
python3 -I /tmp/sim.py > /dev/null 2>&1; python3 /tmp/sim.py
